import path from "node:path";
import { fileURLToPath } from "node:url";

import { build } from "esbuild";

export const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const workerEntry = "apps/model-studio/model-pack-worker-entry.js";
export const workerOutput = "assets/js/model-pack-worker.js";

export async function createModelPackWorkerBundle() {
  const result = await build({
    absWorkingDir: repositoryRoot,
    entryPoints: [workerEntry],
    outfile: workerOutput,
    bundle: true,
    write: false,
    format: "esm",
    platform: "browser",
    target: ["es2022"],
    charset: "ascii",
    legalComments: "none",
    sourcemap: false,
    minify: false,
    treeShaking: true,
    banner: {
      js: "// Generated by npm run build:worker. Do not edit directly."
    }
  });
  if (result.outputFiles.length !== 1) {
    throw new Error(`Expected one worker bundle, received ${result.outputFiles.length}.`);
  }
  return result.outputFiles[0].text;
}
